for name in ('CurrentTask','ConversationHandoff','SessionLog','DevelopmentSchedule'):
    p=ROOT/'ProjectDocs/AI'/f'{name}.md';s=p.read_text();assert s==(BASE/'Sources/Before'/p.relative_to(ROOT)).read_text()
